{
  "commonPhenomenon": "平台订单终态为关闭，但支付渠道交易终态显示成功，存在状态不一致。",
  "facts": [
    {
      "statement": "平台订单的终态为关闭。",
      "evidenceIds": [
        "E-036"
      ]
    },
    {
      "statement": "支付渠道的交易终态显示为成功。",
      "evidenceIds": [
        "E-036"
      ]
    }
  ],
  "differences": [
    {
      "description": "平台侧记录的资金/业务状态（关闭）与通道侧记录的可信结果（成功）发生冲突。",
      "evidenceIds": [
        "E-036"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "通道在平台关单后返回了迟到的成功通知或查单结果，导致状态采集时间差引发的表面冲突。",
      "evidenceIds": [
        "E-036"
      ],
      "verification": "核对关单请求时间、通道应答时间及成功通知到达时间的时间戳与时区；通过可信只读查单确认当前资金实际结果。"
    },
    {
      "hypothesis": "平台与通道对同一笔交易的终态映射逻辑存在差异，或旧快照数据造成误判。",
      "evidenceIds": [
        "E-036"
      ],
      "verification": "比对商户订单号、通道交易号和商户号是否指向同一交易；检查状态采集来源及通道状态映射规则。"
    },
    {
      "hypothesis": "平台未收到通道的成功回调，导致平台侧未能更新状态而执行了关单操作。",
      "evidenceIds": [
        "E-036"
      ],
      "verification": "检查平台入口访问日志和商户通知应答记录，确认是否存在回调投递失败、网络失败或验签失败的情况。"
    }
  ],
  "checkSteps": [
    "确认商户订单号、通道交易号和商户号均指向同一笔交易。",
    "比较状态采集时间、时区、来源及通道状态映射规则。",
    "查看回调投递记录、查单结果和人工操作审计日志。",
    "获取新的只读查单结果以确认真实资金状态。",
    "由有权限的人员按业务流程复核后续处理。"
  ],
  "missingInformation": [
    "具体的关单请求时间与通道成功通知到达时间的精确时间戳对比。",
    "通道对该笔交易的确切最终资金流水记录。",
    "平台侧接收回调的详细日志（包括时间、状态码、验签结果）。"
  ],
  "knowledgeCitations": [
    "terminal-conflict",
    "late-success-after-close",
    "lost-callback"
  ],
  "knowledgeOmissionReason": null
}
